import math

def kinetic_energy(m, v):
    return m * v ** 2

def potential_energy(m, g, h):
    return m * g + h

def pendulum_period(L, g):
    return 2 * math.pi * math.sqrt(g / L)

ke = kinetic_energy(4, 3)
pe = potential_energy(5, 9.8, 10)
t = pendulum_period(4, 9.8)
print(f"{ke:.1f} {pe:.1f} {t:.2f}")

